import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { startServer } from "../services/sportsdesk_webview_server.ts";

/**
 * The graph page is generated by `scripts/graph_feed_poller_daemon.ts` and fetches its data
 * relative to the document, so serving the HTML alone leaves it dead. These assertions lock in
 * the data plane it needs.
 */
describe("graph data plane", () => {
  let server: ReturnType<typeof startServer>;

  beforeAll(() => {
    server = startServer({
      port: 0,
      hostname: "127.0.0.1",
      development: false,
    });
  });

  afterAll(() => {
    server.stop(true);
  });

  const get = (path: string) => fetch(`${server.url}${path}`);

  test("serves the graph page and both of its modules", async () => {
    const page = await get("graph");
    expect(page.status).toBe(200);
    expect(page.headers.get("content-type")).toContain("text/html");

    // graph.js imports two page modules from assets/; a 404 on either kills hydration.
    for (const path of [
      "graph.js",
      "assets/live-ops.js",
      "assets/gslive-links.js",
    ]) {
      const script = await get(path);
      expect(script.status).toBe(200);
      expect(script.headers.get("content-type")).toContain("javascript");
    }
  });

  test("serves the live feed at both paths the page documents", async () => {
    for (const path of ["graph-live-feed.json", "api/graph-feed"]) {
      const res = await get(path);
      expect(res.status).toBe(200);
      expect(res.headers.get("cache-control")).toBe("no-store");
      const feed = (await res.json()) as {
        schemaVersion: unknown;
        dataMode: unknown;
        pendingBets: unknown[];
      };
      expect(feed.schemaVersion).toBeDefined();
      expect(feed.dataMode).toBeString();
      expect(Array.isArray(feed.pendingBets)).toBe(true);
    }
  });

  describe("companion JSON the graph module fetches", () => {
    const FILES = ["combo-uniqueness.json", "cross-domain-bridge.json"];
    const TOKEN = "test-admin-token-not-a-secret";
    let saved: string | undefined;

    beforeAll(() => {
      saved = Bun.env["SPORTSDESK_ADMIN_TOKEN"];
    });
    afterAll(() => {
      if (saved === undefined)
        Reflect.deleteProperty(Bun.env, "SPORTSDESK_ADMIN_TOKEN");
      else Reflect.set(Bun.env, "SPORTSDESK_ADMIN_TOKEN", saved);
    });

    test("is refused without a token, even from loopback", async () => {
      Reflect.set(Bun.env, "SPORTSDESK_ADMIN_TOKEN", TOKEN);
      for (const path of FILES) {
        const none = await get(path);
        expect(none.status).toBe(401);
        const wrong = await fetch(`${server.url}${path}`, {
          headers: { authorization: "Bearer not-the-token" },
        });
        expect(wrong.status).toBe(401);
        expect(await wrong.text()).not.toContain("customersInBook");
      }
    });

    test("is refused (503) when the server has no admin token configured", async () => {
      Reflect.deleteProperty(Bun.env, "SPORTSDESK_ADMIN_TOKEN");
      for (const path of FILES) {
        expect((await get(path)).status).toBe(503);
      }
    });

    test("is served with the admin token", async () => {
      Reflect.set(Bun.env, "SPORTSDESK_ADMIN_TOKEN", TOKEN);
      for (const path of FILES) {
        const res = await fetch(`${server.url}${path}`, {
          headers: { authorization: `Bearer ${TOKEN}` },
        });
        expect(res.status).toBe(200);
        expect(res.headers.get("content-type")).toContain("application/json");
      }
    });
  });

  test("serves graph assets", async () => {
    const svg = await get("assets/pipeline-6-layer-data-cleaning.svg");
    expect(svg.status).toBe(200);
    expect(svg.headers.get("content-type")).toContain("image/svg+xml");

    const meta = await get("assets/pipeline-artifacts-metadata.json");
    expect(meta.status).toBe(200);
    expect(meta.headers.get("content-type")).toContain("application/json");
  });

  test("refuses to escape the assets directory", async () => {
    for (const path of [
      "assets/%2e%2e%2fpackage.json",
      "assets/../package.json",
    ]) {
      const res = await get(path);
      // Either the router normalises the path or the guard rejects it; both must not leak.
      expect([400, 404]).toContain(res.status);
      expect(await res.text()).not.toContain("sportsdesk-ops");
    }
  });

  test("404s an unknown asset instead of throwing", async () => {
    const res = await get("assets/does-not-exist.png");
    expect(res.status).toBe(404);
  });

  test("serves the agent tree joined with the wager rollup", async () => {
    const res = await get("api/agent-tree");
    expect(res.status).toBe(200);
    expect(res.headers.get("cache-control")).toBe("no-store");

    const tree = (await res.json()) as {
      schemaVersion: number;
      agentCount: number;
      roots: string[];
      nodes: Record<
        string,
        { l: number | null; p: string | null; t: string | null }
      >;
      counts: Record<string, { games: number; wagered: number }>;
    };

    expect(tree.schemaVersion).toBe(1);
    expect(tree.agentCount).toBeGreaterThan(0);
    expect(tree.roots.length).toBeGreaterThan(0);

    // Every parent pointer must resolve inside the same file.
    for (const [key, node] of Object.entries(tree.nodes)) {
      expect(typeof key).toBe("string");
      if (node.p !== null) expect(tree.nodes[node.p]).toBeDefined();
    }
    for (const root of tree.roots) expect(tree.nodes[root]?.p).toBeNull();

    // Exposure is reported only for agents that actually appear in the capture.
    for (const [key, count] of Object.entries(tree.counts)) {
      expect(tree.nodes[key]).toBeDefined();
      expect(count.games).toBeGreaterThan(0);
    }
  });
});
